import{_ as e,o as t,c as a,a0 as i}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /build-templates","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/build-templates.md","filePath":"references/skills/build-templates.md"}'),c={name:"references/skills/build-templates.md"};function o(l,n,h,s,d,r){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="skill-build-templates" tabindex="-1">Skill: <code>/build-templates</code> <a class="header-anchor" href="#skill-build-templates" aria-label="Permalink to &quot;Skill: `/build-templates`&quot;">​</a></h1><div class="warning custom-block github-alert"><p class="custom-block-title">Đang phát triển (WIP)</p><p>Kỹ năng này hiện tại vẫn đang trong giai đoạn phát triển và thử nghiệm ban đầu (chưa hoàn thiện 100% mượt mà). Hãy cẩn thận kiểm tra lại kết quả khi sử dụng.</p></div><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>build-templates</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/build-templates</code></li><li>Dùng khi khởi tạo dự án mới hoặc khi có sự thay đổi lớn về thư viện UI/Core ở phía mã nguồn Frontend/Backend.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>File cấu hình <code>platform-repos.local.json</code> (Để định vị đường dẫn thư mục code FE/BE).</li><li>Các file <code>package.json</code> của FE/BE.</li><li>Các file Component dùng chung (Breadcrumb, Layout, Form, Table) trong mã nguồn Frontend.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Sinh ra các file giao diện EJS (<code>.ejs</code>) bên trong thư mục <code>.flowgrid/templates/</code> (ví dụ: <code>default-layout.ejs</code>).</li><li>Tự động sinh hoặc cập nhật các file đặc tả YAML dùng chung (<code>surfaces/common/yaml/</code>).</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Để hệ thống có thể tự động sinh code (gencode) cho cả Frontend, Backend, và Test E2E, FlowGrid hiện đang cần gắn liền với một bộ base có sẵn của các công nghệ như Nuxt4, Next.js, Python FastAPI, Laravel... với các cấu trúc thư mục, file mẫu, và common code định sẵn.</li><li><strong>Vấn đề đặt ra:</strong> Khi áp dụng vào các dự án có sẵn, đôi khi dự án đó không tuân thủ đúng base tiêu chuẩn của công nghệ, hoặc dùng chung công nghệ nhưng lại khác cấu trúc layout, thư viện dùng chung. Ví dụ: base FE mặc định của FlowGrid dùng <code>shadcn-ui</code>, nhưng một dự án khác lại dùng <code>vuetify</code>.</li><li><strong>Giải pháp của <code>/build-templates</code>:</strong> Kỹ năng này sẽ làm nhiệm vụ &quot;đọc vị&quot; base code thực tế của dự án đích. Sau đó, nó tự động build lại toàn bộ các template (<code>.ejs</code>, v.v.) để cung cấp đầu vào chuẩn xác cho các script sinh code (codegen, testgen). Nhờ đó, tính năng sinh code sẽ &quot;nhập gia tùy tục&quot; và tuân thủ đúng chuẩn của dự án hiện tại thay vì ép buộc dùng base mặc định.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Yêu cầu chạy <code>/configure-repo-maps</code> nếu chưa liên kết thư mục mã nguồn.</li><li><strong>Sau đó:</strong> Chạy lệnh <code>pnpm docs:render</code> để biên dịch thử và xem kết quả giao diện các template EJS mới.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Không tự ý ghi đè:</strong> Nếu các file template EJS đã tồn tại và có dấu hiệu chỉnh sửa bằng tay của con người, Agent phải hỏi ý kiến User trước khi ghi đè, hoặc chỉ vá phần chênh lệch.</li><li>Không được phép thay đổi hoặc xóa các thẻ neo HTML Comment (Ví dụ: <code>&lt;!-- flowgrid-anchor: ... --&gt;</code>) trong file EJS vì hệ thống bộ docs dựa vào đó để nhét nội dung động vào.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/build-templates</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',21)])])}const p=e(c,[["render",o]]);export{g as __pageData,p as default};
